* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: 'Segoe UI', sans-serif;
  background: #f7fafc;
  padding: 32px 16px;
  color: #2d3748;
}

.container {
  max-width: 720px;
  margin: 0 auto;
}

h1 { font-size: 1.8em; margin-bottom: 4px; }
.subtitle { color: #718096; margin-bottom: 24px; font-size: 0.9em; }
.subtitle a { color: #4299e1; }

.search-row {
  display: flex;
  gap: 10px;
  margin-bottom: 20px;
}

input {
  flex: 1;
  padding: 10px 14px;
  border: 1px solid #cbd5e0;
  border-radius: 8px;
  font-size: 1em;
}

input:focus { outline: none; border-color: #4299e1; }

button {
  background: #4299e1;
  color: white;
  border: none;
  padding: 10px 22px;
  border-radius: 8px;
  font-size: 1em;
  cursor: pointer;
  white-space: nowrap;
}

button:hover { background: #3182ce; }

#status { color: #718096; font-size: 0.9em; margin-bottom: 12px; min-height: 20px; }

.result {
  background: white;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 16px;
  margin-bottom: 12px;
}

.result h3 { color: #2b6cb0; margin-bottom: 6px; font-size: 1em; }
.result p  { color: #4a5568; font-size: 0.88em; line-height: 1.5; }
.result .meta { color: #a0aec0; font-size: 0.78em; margin-top: 8px; }

const API_BASE = 'https://api.fda.gov/drug/label.json';

async function search() {
  const query = document.getElementById('query').value.trim();
  if (!query) return;

  const status  = document.getElementById('status');
  const results = document.getElementById('results');

  status.textContent  = 'Searching...';
  results.innerHTML   = '';

  try {
    const url = `${API_BASE}?search=openfda.brand_name:"${encodeURIComponent(query)}"+openfda.generic_name:"${encodeURIComponent(query)}"&limit=5`;
    const res  = await fetch(url);

    if (res.status === 404) {
      status.textContent = 'No results found.';
      return;
    }

    if (!res.ok) throw new Error(`API error: ${res.status}`);

    const data = await res.json();
    const hits = data.results || [];

    status.textContent = `Found ${data.meta?.results?.total ?? hits.length} result(s). Showing ${hits.length}.`;

    hits.forEach(hit => {
      const name    = hit.openfda?.brand_name?.[0] || hit.openfda?.generic_name?.[0] || 'Unknown';
      const generic = hit.openfda?.generic_name?.[0] || '';
      const purpose = (hit.purpose?.[0] || hit.indications_and_usage?.[0] || 'No description available.')
                        .substring(0, 300);
      const mfr     = hit.openfda?.manufacturer_name?.[0] || '';

      const card = document.createElement('div');
      card.className = 'result';
      card.innerHTML = `
        <h3>${name}${generic && generic !== name ? ` <span style="font-weight:400;color:#718096;">(${generic})</span>` : ''}</h3>
        <p>${purpose}${purpose.length === 300 ? '...' : ''}</p>
        ${mfr ? `<div class="meta">Manufacturer: ${mfr}</div>` : ''}
      `;
      results.appendChild(card);
    });

  } catch (e) {
    status.textContent = `Error: ${e.message}`;
  }
}

// Search on Enter key
document.getElementById('query').addEventListener('keydown', e => {
  if (e.key === 'Enter') search();
});
